-- Gestor de Anúncios (Fase 1): registro de tudo que o sistema lançou na Meta.
CREATE TABLE IF NOT EXISTS ads_lancamentos(id INT AUTO_INCREMENT PRIMARY KEY,chave VARCHAR(64) NOT NULL,quem VARCHAR(80) NOT NULL DEFAULT '',quando VARCHAR(40) NOT NULL,tipo VARCHAR(20) NOT NULL DEFAULT 'IMPULSIONAR',referencia VARCHAR(120) NOT NULL DEFAULT '',titulo VARCHAR(200) NOT NULL DEFAULT '',objetivo VARCHAR(30) NOT NULL DEFAULT '',orcamento_dia DECIMAL(14,2) NOT NULL DEFAULT 0,dias INT NOT NULL DEFAULT 0,inicio VARCHAR(40) NOT NULL DEFAULT '',fim VARCHAR(40) NOT NULL DEFAULT '',compromisso DECIMAL(14,2) NOT NULL DEFAULT 0,moeda VARCHAR(8) NOT NULL DEFAULT '',publico VARCHAR(1000) NOT NULL DEFAULT '',campanha_id VARCHAR(64) NOT NULL DEFAULT '',conjunto_id VARCHAR(64) NOT NULL DEFAULT '',anuncio_id VARCHAR(64) NOT NULL DEFAULT '',estado VARCHAR(20) NOT NULL DEFAULT 'CRIANDO',erro VARCHAR(600) NOT NULL DEFAULT '',atualizado_em VARCHAR(40) NOT NULL,UNIQUE KEY uq_adsl_chave (chave)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
